export async function mapLimit(items, limit, worker) {
  if (!Array.isArray(items)) {
    throw new TypeError('items must be an Array');
  }
  if (typeof limit !== 'number' || limit <= 0 || !Number.isSafeInteger(limit)) {
    throw new TypeError('limit must be a positive safe integer');
  }
  if (typeof worker !== 'function') {
    throw new TypeError('worker must be a function');
  }

  if (items.length === 0) {
    return [];
  }

  const snapshot = Array.from(items);
  const results = new Array(snapshot.length);
  let firstError = null;
  let nextIndex = 0;
  let stopped = false;
  let activeCount = 0;

  return new Promise((resolve, reject) => {
    function tryStartWorker() {
      if (stopped || nextIndex >= snapshot.length || activeCount >= limit) {
        return;
      }

      activeCount++;
      const index = nextIndex;
      const value = snapshot[index];
      nextIndex++;

      let result;
      try {
        result = worker(value, index);
      } catch (error) {
        activeCount--;
        if (firstError === null) {
          firstError = error;
          stopped = true;
        }
        checkComplete();
        return;
      }

      if (result && typeof result.then === 'function') {
        try {
          result.then(
            value => {
              results[index] = value;
              activeCount--;
              if (!stopped) {
                tryStartWorker();
              }
              checkComplete();
            },
            error => {
              activeCount--;
              if (firstError === null) {
                firstError = error;
                stopped = true;
              }
              checkComplete();
            }
          );
        } catch (error) {
          activeCount--;
          if (firstError === null) {
            firstError = error;
            stopped = true;
          }
          checkComplete();
        }
      } else {
        results[index] = result;
        activeCount--;
        if (!stopped) {
          tryStartWorker();
        }
        checkComplete();
      }
    }

    function checkComplete() {
      if (activeCount === 0) {
        if (firstError !== null) {
          reject(firstError);
        } else if (nextIndex >= snapshot.length) {
          resolve(results);
        }
      }
    }

    const initialWorkers = Math.min(limit, snapshot.length);
    for (let i = 0; i < initialWorkers; i++) {
      tryStartWorker();
    }
  });
}

