export async function mapLimit(items, limit, worker) {
  // Validate arguments
  if (!Array.isArray(items)) {
    throw new TypeError('items must be an Array');
  }
  if (!Number.isSafeInteger(limit) || limit <= 0) {
    throw new TypeError('limit must be a positive safe integer');
  }
  if (typeof worker !== 'function') {
    throw new TypeError('worker must be a function');
  }

  // Handle empty array
  if (items.length === 0) {
    return [];
  }

  // Snapshot the input array
  const snapshot = Array.from(items);
  const results = new Array(snapshot.length);

  // State management
  let nextIndex = 0;
  let activeCount = 0;
  let failure = null;
  let settled = false;

  return new Promise((resolve, reject) => {
    const settle = () => {
      if (settled) return;
      settled = true;
      if (failure !== null) {
        reject(failure);
      } else {
        resolve(results);
      }
    };

    const startWork = (index) => {
      activeCount++;

      let workPromise;
      try {
        workPromise = Promise.resolve(worker(snapshot[index], index));
      } catch (error) {
        if (failure === null) {
          failure = error;
        }
        activeCount--;
        tryAdmitNext();
        return;
      }

      workPromise.then(
        (result) => {
          results[index] = result;
          activeCount--;
          tryAdmitNext();
        },
        (error) => {
          if (failure === null) {
            failure = error;
          }
          activeCount--;
          tryAdmitNext();
        }
      );
    };

    const tryAdmitNext = () => {
      if (failure === null && nextIndex < snapshot.length) {
        startWork(nextIndex++);
      } else if (activeCount === 0) {
        settle();
      }
    };

    // Admit initial batch of work
    while (nextIndex < snapshot.length && activeCount < limit && failure === null) {
      startWork(nextIndex++);
    }

    // Settle if no work was admitted
    if (activeCount === 0) {
      settle();
    }
  });
}
